// Шаг цепочки Сметы. Смете и уточнениям — шаблоны WhatsApp «estimate_ready» и «estimate_reminder»,
// одобренные у Meta на pl и en (docs/whatsapp-setup.md, параметры — название Сметы и сумма), текст SMS —
// те же два языка. Последний шаг — Задача человеку на польском: её читают сотрудники Заказчика.
const TEMPLATES = { sent: 'estimate_ready', reminder_1: 'estimate_reminder', reminder_2: 'estimate_reminder' };
const TEXTS = {
  estimate_ready: {
    pl: (company, name, amount) => `${company}: kosztorys naprawy „${name}” jest gotowy: ${amount}. Odpisz nam, czy go akceptujesz.`,
    en: (company, name, amount) => `${company}: the repair estimate "${name}" is ready: ${amount}. Please reply whether you accept it.`,
  },
  estimate_reminder: {
    pl: (company, name, amount) => `${company}: przypominamy o kosztorysie naprawy „${name}”: ${amount}. Odpisz nam, czy go akceptujesz.`,
    en: (company, name, amount) => `${company}: a reminder about the repair estimate "${name}": ${amount}. Please reply whether you accept it.`,
  },
};
const CHANNELS = { messenger: 'Messenger', instagram: 'Instagram', whatsapp: 'WhatsApp' };

function money(amount, currency, language) {
  const value = Number(amount).toFixed(2);
  return `${language === 'pl' ? value.replace('.', ',') : value} ${currency}`;
}

function message(r) {
  const language = r.language === 'pl' ? 'pl' : 'en';
  const amount = money(r.amount, r.currency, language);
  const template = TEMPLATES[r.step];
  return {
    text: TEXTS[template][language](r.company, r.name, amount),
    template: { name: template, parameters: [r.name, amount] },
  };
}

function silentTask(r) {
  return {
    task: {
      kind: 'estimate_silent',
      parent_type: 'RepairOrder',
      parent_id: r.crm_repair_order_id,
      name: `Klient milczy po kosztorysie: ${r.name}`,
      description: [
        `Kosztorys „${r.name}” (${money(r.amount, r.currency, 'pl')}) wysłany klientowi, dwa przypomnienia bez odpowiedzi.`,
        'Skontaktuj się z klientem i ustaw status kosztorysu.',
        `Kanał: ${CHANNELS[r.channel]} · ${r.sender_id}`,
      ].join('\n'),
    },
  };
}

// Postgres-узел без строк отдаёт один item без полей — делать нечего.
return $input.all().filter((item) => item.json.step).map(({ json: r }) => ({
  json: {
    crm_estimate_id: r.crm_estimate_id,
    step: r.step,
    conversation_id: r.conversation_id,
    ...(r.step === 'silent_task' ? silentTask(r) : message(r)),
  },
}));
